import{_ as a,o as t,c as l,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Performance Meeting 2022-08-04","description":"","frontmatter":{"title":"Ceph Performance Meeting 2022-08-04","date":"2022-08-04T00:00:00.000Z","updated":"2022-08-06T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","PR 讨论","协作开发"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Performance_Meeting_2022-08-04.md","filePath":"posts/2022/Ceph_Performance_Meeting_2022-08-04.md","lastUpdated":1780460162000}'),i={name:"posts/2022/Ceph_Performance_Meeting_2022-08-04.md"};function r(n,e,s,h,d,c){return t(),l("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><ul><li><strong>日期</strong>: 2022-08-04</li><li><strong>参会人员</strong>: [参会人员名单]</li><li><strong>主持人</strong>: [主持人姓名]</li><li><strong>记录人</strong>: [记录人姓名]</li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>PR 讨论</strong></p><ul><li><strong>Ronin 的 PR</strong>: 有关 Ronin 提交的字符串计算函数性能提升的 PR 讨论中，性能提升了 15%，尽管改动较小，但有助于未来的回归测试。</li><li><strong>Rex TV Store 的 PR</strong>: 讨论了关于 Rex TV Store 的 PR，特别是在 Rock CP 设置的重新调整上，Adam 对大幅度改变现有设置表示担忧，特别是读取放大效应。讨论了可能的改进方向，包括压缩和针对不同列族的默认设置。</li><li><strong>其他 PR 更新</strong>: Igor 的 PR 关于消除 statifes 更新，已进行更多修复。RGW Bench 的 PR 关于原子写入基准测试，Dang 进行了审查并进行了进一步讨论。</li></ul></li><li><p><strong>性能优化讨论</strong></p><ul><li><strong>Boost Valgrind 默认启用</strong>: 讨论了是否默认启用 Boost Valgrind，Mark Cogan 的测试显示可能有一些性能影响，但影响不大。会议决定进一步测试以验证。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>深入讨论和测试 Rex TV Store 的 PR，特别是关于读取放大和写入放大的平衡问题。</li><li>对 Boost Valgrind 的默认启用进行进一步的性能测试，特别是关注 OSD 方面的影响。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>Ronin 继续监控其 PR 的性能影响。</li><li>Adam 和主持人继续讨论和优化 Rex TV Store 的 PR。</li><li>主持人进行 Boost Valgrind 的进一步性能测试。</li><li>所有相关人员继续关注和更新各自的 PR 进展。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>会议最后，Mark 和主持人讨论了与性能无关的其他事项，并决定在另一个会议中继续讨论。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li>会议在确认无其他议题后结束，主持人祝愿大家有一个愉快的一周，并期待下周的会议。</li></ul><p>会议纪要准确反映了原始内容的要点，涵盖了会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划。以下是对原总结的改进：</p><ol><li>确保了所有关键信息，包括 PR 讨论的具体内容，性能优化讨论的细节，决定事项和行动计划都被包含在内。</li><li>确保了 Ceph 相关领域的英文原文关键词被保留，如 PR、Rex TV Store、Rock CP、Boost Valgrind、Valgrind、RGW Bench、statifes、原子写入、基准测试等。</li><li>确保了会议纪要的格式和内容符合专业要求。</li></ol>',15)])])}const P=a(i,[["render",r]]);export{u as __pageData,P as default};
